head.script:
scwin.multiDown = function(grid1id, grid2id) {
    var options = {
        common: {
            fileName: "sample.xls",
            showProcess: false
        },
        //excelInfo에 각 그리드의 정보를 입력한다.
        excelInfo: [{
                gridId: grid1id,
                sheetName: "첫번째 sheet",
                removeColumns: ""
            },
            {
                gridId: grid2id,
                sheetName: "두번째 sheet",
                removeColumns: ""
            }
        ]
    };
    WebSquare.util.multipleExcelDownload(options);
};
scwin.trigger1_onclick = function(e) {
    scwin.multiDown("gridView1", "gridView2");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. xp환경의 IE6, IE7에서 샘플파일을 실행한다.
    //1. Execute the sample file in IE6 and IE7 of xp environment.
    //Verify 1. 정상적으로 그리드의 데이터가 보여진다.(이전에는 '개체가 이 속성 또는 메서더를 지원하지 않습니다.'메시지 발생하고 그리드와 데이터가 보여지지 않음)
    //1. The grid"s data is normally displayed (previously the 'object does not support this property or metadata' message and the grid and data are not shown)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').innerText == '1000'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_cell_0_1').innerText == '1000'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //sampleData1
    window.data1 = [{
            "col1": "a",
            "col2": "1000"
        },
        {
            "col1": "b",
            "col2": "2000"
        },
        {
            "col1": "c",
            "col2": "3000"
        },
        {
            "col1": "d",
            "col2": "4000"
        }
    ];
    //sampleData2
    window.data2 = [{
            "col1": "a",
            "col2": "1000"
        },
        {
            "col1": "c",
            "col2": "3000"
        }
    ];
    dataList1.setJSON(data1);
    dataList2.setJSON(data2);
    //MultiExcelDownload Function
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 21-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
